// Service worker for /chess/ only (it lives in this folder, so its scope can't reach the rest of the site).
// Strategy: network first (always fresh online), cache fallback (works offline).
// The file list and version come from offline-files.json, generated by scripts/build-offline.mjs.
const PREFIX = 'chess-academy-';

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const res = await fetch('offline-files.json', { cache: 'no-store' });
    const { version, files } = await res.json();
    const cache = await caches.open(PREFIX + version);
    await cache.addAll(files);
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const res = await fetch('offline-files.json', { cache: 'no-store' }).catch(() => null);
    const current = res ? PREFIX + (await res.json()).version : null;
    if (current) for (const k of await caches.keys()) if (k.startsWith(PREFIX) && k !== current && k !== PREFIX + 'fonts') await caches.delete(k);
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  // Google Fonts: cache first (they never change at a given URL)
  if (url.hostname === 'fonts.googleapis.com' || url.hostname === 'fonts.gstatic.com') {
    event.respondWith(caches.open(PREFIX + 'fonts').then(async (c) => (await c.match(req)) || fetch(req).then((r) => { if (r.ok || r.type === 'opaque') c.put(req, r.clone()); return r; })));
    return;
  }
  if (url.origin !== location.origin || !url.pathname.startsWith(new URL(self.registration.scope).pathname)) return;
  event.respondWith((async () => {
    try {
      const fresh = await fetch(req);
      if (fresh.ok) {
        const keys = (await caches.keys()).filter((k) => k.startsWith(PREFIX) && k !== PREFIX + 'fonts');
        if (keys.length) (await caches.open(keys[keys.length - 1])).put(req, fresh.clone());
      }
      return fresh;
    } catch {
      const cached = await caches.match(req, { ignoreSearch: true });
      if (cached) return cached;
      if (req.mode === 'navigate') return caches.match('./');
      throw new Error('offline and not cached: ' + url.pathname);
    }
  })());
});
